CREATE TABLE public.crm_contracts (
    id integer DEFAULT nextval('public.crm_contracts_id_seq'::regclass) NOT NULL,
    contract_code character varying(50) NOT NULL,
    contract_name character varying(200) NOT NULL,
    customer_id integer NOT NULL,
    opportunity_id integer,
    quotation_id integer,
    contract_type character varying(50),
    start_date date,
    end_date date,
    currency character varying(10) DEFAULT 'CNY'::character varying,
    total_amount numeric(15,2) NOT NULL,
    paid_amount numeric(15,2) DEFAULT 0,
    unpaid_amount numeric(15,2) GENERATED ALWAYS AS ((total_amount - paid_amount)) STORED,
    status character varying(20) DEFAULT 'draft'::character varying,
    approval_status character varying(20) DEFAULT 'pending'::character varying,
    approved_by integer,
    approved_at timestamp(6) without time zone,
    signed_date date,
    signed_by_customer character varying(100),
    signed_by_company character varying(100),
    contract_file_url character varying(500),
    owner_id integer,
    terms_conditions text,
    remark text,
    created_id integer,
    created_time timestamp(6) without time zone DEFAULT now(),
    updated_id integer,
    updated_time timestamp(6) without time zone DEFAULT now(),
    is_deleted boolean DEFAULT false,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer
);


