--

CREATE TABLE public.crm_customer_health (
    id integer DEFAULT nextval('public.crm_customer_health_id_seq'::regclass) NOT NULL,
    customer_id integer NOT NULL,
    health_score integer DEFAULT 50,
    health_level character varying(20) DEFAULT 'medium'::character varying,
    product_usage_score integer,
    support_tickets_score integer,
    payment_score integer,
    engagement_score integer,
    satisfaction_score integer,
    risk_factors json,
    risk_level character varying(20) DEFAULT 'low'::character varying,
    contract_end_date date,
    renewal_probability integer,
    renewal_status character varying(20),
    assessed_at timestamp(6) without time zone DEFAULT now(),
    next_assessment_date date,
    updated_time timestamp(6) without time zone DEFAULT now(),
    created_id integer,
    updated_id integer,
    created_time timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer,
    owner_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL
);


