--

CREATE TABLE public.crm_customer_health_scores (
    id bigint DEFAULT nextval('public.crm_customer_health_scores_id_seq'::regclass) NOT NULL,
    customer_id bigint NOT NULL,
    score_date date NOT NULL,
    overall_score integer NOT NULL,
    health_level character varying(20) NOT NULL,
    dimension_scores jsonb DEFAULT '{}'::jsonb NOT NULL,
    product_usage jsonb DEFAULT '{}'::jsonb,
    adoption_rate numeric(5,2) DEFAULT 0,
    engagement_score integer DEFAULT 0,
    avg_contact_frequency numeric(5,2) DEFAULT 0,
    last_interaction_date date,
    payment_score integer DEFAULT 0,
    revenue_trend character varying(20),
    arpu numeric(18,2) DEFAULT 0,
    satisfaction_score integer DEFAULT 0,
    nps_score integer,
    last_survey_date date,
    risk_indicators text[],
    churn_signals text[],
    churn_probability numeric(5,2) DEFAULT 0,
    expansion_probability numeric(5,2) DEFAULT 0,
    ai_insights jsonb DEFAULT '{}'::jsonb,
    created_time timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    created_id bigint,
    version integer DEFAULT 1,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer,
    owner_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL,
    CONSTRAINT crm_customer_health_scores_overall_score_check CHECK (((overall_score >= 0) AND (overall_score <= 100)))
);


