--
-- Name: crm_customer_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_customer_profiles (
    id bigint DEFAULT nextval('public.crm_customer_profiles_id_seq'::regclass) NOT NULL,
    customer_id bigint NOT NULL,
    basic_profile jsonb DEFAULT '{}'::jsonb,
    behavior_profile jsonb DEFAULT '{}'::jsonb,
    preference_profile jsonb DEFAULT '{}'::jsonb,
    value_profile jsonb DEFAULT '{}'::jsonb,
    purchase_patterns jsonb DEFAULT '{}'::jsonb,
    preferred_products jsonb DEFAULT '{}'::jsonb,
    price_sensitivity character varying(20),
    buying_stages character varying(20),
    communication_prefs jsonb DEFAULT '{}'::jsonb,
    best_contact_times character varying(20)[],
    preferred_channels character varying(20)[],
    lifetime_value numeric(18,2),
    churn_probability numeric(5,2),
    upsell_probability numeric(5,2),
    referral_probability numeric(5,2),
    personas character varying(50)[],
    tags character varying(50)[],
    analysis_count integer DEFAULT 0,
    last_analysis_at timestamp(6) with time zone,
    model_version character varying(50),
    confidence_score numeric(5,2),
    data_completeness numeric(5,2),
    created_time timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_time timestamp(6) with time zone,
    version integer DEFAULT 1,
    created_id integer,
    updated_id integer,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer,
    owner_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL
);


