--
-- Name: crm_customers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_customers (
    id integer DEFAULT nextval('public.crm_customers_id_seq'::regclass) NOT NULL,
    customer_code character varying(50) NOT NULL,
    customer_name character varying(200) NOT NULL,
    customer_type character varying(20) DEFAULT 'enterprise'::character varying,
    industry character varying(100),
    source character varying(50),
    customer_status character varying(20) DEFAULT 'active'::character varying,
    owner_id integer,
    department_id integer,
    lead_id integer,
    pool_status character varying(20) DEFAULT 'private'::character varying,
    last_followup_at timestamp(6) without time zone,
    next_followup_at timestamp(6) without time zone,
    created_time timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_time timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP,
    created_id integer,
    updated_id integer,
    customer_short_name character varying(100),
    customer_level character varying(20) DEFAULT 'C'::character varying,
    scale character varying(20),
    registration_no character varying(50),
    tax_no character varying(50),
    legal_person character varying(100),
    established_date date,
    registered_capital numeric(18,2),
    paid_capital numeric(18,2),
    website character varying(255),
    main_phone character varying(50),
    main_email character varying(255),
    country character varying(50) DEFAULT '中国'::character varying,
    province character varying(50),
    city character varying(50),
    district character varying(50),
    address character varying(500),
    rating integer DEFAULT 3,
    territory character varying(100),
    customer_since date,
    first_order_date date,
    last_order_date date,
    total_revenue numeric(18,2) DEFAULT 0,
    total_orders integer DEFAULT 0,
    credit_limit numeric(18,2) DEFAULT 0,
    outstanding_amount numeric(18,2) DEFAULT 0,
    payment_days integer DEFAULT 0,
    parent_customer_id integer,
    is_parent boolean DEFAULT false,
    customer_segment character varying(50),
    churn_risk character varying(20),
    description text,
    extra_data jsonb DEFAULT '{}'::jsonb,
    version integer DEFAULT 1,
    protection_deadline timestamp(6) without time zone,
    claim_time timestamp(6) without time zone,
    health_score numeric(5,2),
    duplicate_check_key character varying(200),
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL,
    dept_id integer,
    CONSTRAINT crm_customers_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);


