--

CREATE TABLE public.crm_order_items (
    id integer DEFAULT nextval('public.crm_order_items_id_seq'::regclass) NOT NULL,
    order_id integer NOT NULL,
    product_id integer,
    product_code character varying(50),
    product_name character varying(200) NOT NULL,
    sku_id integer,
    sku_code character varying(50),
    quantity numeric(10,2) NOT NULL,
    unit_price numeric(15,2) NOT NULL,
    discount_rate numeric(5,2) DEFAULT 0,
    discount_amount numeric(15,2) DEFAULT 0,
    tax_rate numeric(5,2) DEFAULT 13.00,
    tax_amount numeric(15,2) DEFAULT 0,
    amount numeric(15,2) NOT NULL,
    delivery_date date,
    delivery_address text,
    delivered_quantity numeric(10,2) DEFAULT 0,
    pending_quantity numeric(10,2) GENERATED ALWAYS AS ((quantity - delivered_quantity)) STORED,
    production_status character varying(20) DEFAULT 'pending'::character varying,
    production_note text,
    remark text,
    sort integer DEFAULT 0,
    created_id integer,
    created_time timestamp(6) without time zone DEFAULT now(),
    updated_time timestamp(6) without time zone DEFAULT now(),
    is_deleted boolean DEFAULT false,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer,
    owner_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL
);


