--
-- Name: crm_sales_targets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.crm_sales_targets (
    id integer DEFAULT nextval('public.crm_sales_targets_id_seq'::regclass) NOT NULL,
    owner_id integer NOT NULL,
    target_year integer NOT NULL,
    target_quarter integer,
    target_month integer,
    target_amount numeric(15,2) NOT NULL,
    target_deals integer,
    target_new_customers integer,
    actual_amount numeric(15,2) DEFAULT 0,
    actual_deals integer DEFAULT 0,
    actual_new_customers integer DEFAULT 0,
    completion_rate numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (target_amount > (0)::numeric) THEN ((actual_amount / target_amount) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    created_id integer,
    created_time timestamp(6) without time zone DEFAULT now(),
    updated_time timestamp(6) without time zone DEFAULT now(),
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    description text,
    dept_id integer,
    status character varying(10) DEFAULT '0'::character varying NOT NULL
);


