CREATE TABLE public.crm_tasks (
    id integer DEFAULT nextval('public.crm_tasks_id_seq'::regclass) NOT NULL,
    task_type character varying(50) NOT NULL,
    title character varying(200) NOT NULL,
    description text,
    customer_id integer,
    contact_id integer,
    opportunity_id integer,
    contract_id integer,
    assignee_id integer NOT NULL,
    assigner_id integer,
    due_date date NOT NULL,
    priority character varying(20) DEFAULT 'medium'::character varying,
    status character varying(20) DEFAULT 'pending'::character varying,
    completed_at timestamp(6) without time zone,
    remind_enabled boolean DEFAULT true,
    remind_before_minutes integer DEFAULT 60,
    created_time timestamp(6) without time zone DEFAULT now(),
    updated_time timestamp(6) without time zone DEFAULT now(),
    is_deleted boolean DEFAULT false,
    created_id integer,
    updated_id integer,
    deleted_time timestamp(6) without time zone,
    uuid character varying(64) DEFAULT (gen_random_uuid())::text NOT NULL,
    deleted_id integer,
    dept_id integer,
    owner_id integer
);


