    created_by integer,
    updated_by integer,
    created_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    deleted_at timestamp(6) without time zone,
    remark character varying(500),
    id integer DEFAULT nextval('public.crm_test_monitor_report_id_seq'::regclass) NOT NULL,
    uuid character varying(64) NOT NULL,
    status character varying(10) NOT NULL,
    description text,
    created_time timestamp(6) without time zone NOT NULL,
    updated_time timestamp(6) without time zone NOT NULL,
    created_id integer,
    updated_id integer,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_time timestamp(6) without time zone
);


